-c "import hashlib, html.parser, json, os, pathlib, re, shutil, signal, sys, tempfile, time
import urllib.error, urllib.parse, urllib.request

PORTAL = 'https://eshop.giants-software.com/downloads.php'
UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'
class DLCError(Exception):
    pass

def parse_entries(keys_text, sources_text):
    keys, sources = {}, {}
    for raw in keys_text.replace(chr(10), ';').replace(chr(13), ';').split(';'):
        if not raw.strip():
            continue
        alias, sep, value = raw.partition('=')
        alias, value = alias.strip().lower(), ''.join(value.split()).upper()
        if not sep or not re.fullmatch('[a-z][a-z0-9_-]{0,47}', alias):
            raise DLCError('Invalid DLC key entry; use NAME=KEY separated by semicolons.')
        if alias in keys:
            raise DLCError('Duplicate DLC key name: ' + alias)
        if not re.fullmatch('[A-Z0-9-]{10,80}', value):
            raise DLCError('Invalid product key format for ' + alias)
        keys[alias] = value
    for raw in sources_text.splitlines():
        if not raw.strip():
            continue
        alias, sep, value = raw.partition('=')
        alias, value = alias.strip().lower(), value.strip()
        if not sep or alias not in keys or not value:
            raise DLCError('Every source needs NAME=SOURCE and a matching DLC key name.')
        if alias in sources:
            raise DLCError('Duplicate DLC source name: ' + alias)
        if any(ord(c) < 32 for c in value):
            raise DLCError('Invalid control character in source for ' + alias)
        sources[alias] = value
    return keys, sources

def fingerprint(keys, sources):
    data = json.dumps([keys, sources], sort_keys=True).encode()
    return hashlib.sha256(data).hexdigest()

def digest(path):
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1048576), b''):
            h.update(chunk)
    return h.hexdigest()

def https_url(value):
    p = urllib.parse.urlsplit(value)
    if p.scheme != 'https' or not p.hostname or p.username or p.password or p.fragment:
        raise DLCError('A download source must be a direct HTTPS URL without credentials or a fragment.')
    return p

def kind(path):
    with path.open('rb') as stream:
        header = stream.read(64)
        if header[:2] == b'MZ' and len(header) == 64:
            offset = int.from_bytes(header[60:64], 'little')
            if 64 <= offset <= path.stat().st_size - 4:
                stream.seek(offset)
                if stream.read(4) == bytes((80, 69, 0, 0)):
                    return '.exe'
        stream.seek(32768)
        descriptors = stream.read(2048 * 48)
        if any(descriptors[i + 1:i + 6] in (b'CD001', b'NSR02', b'NSR03') for i in range(0, len(descriptors), 2048)):
            return '.img'
    raise DLCError('The source is not a Windows PE installer or a supported ISO9660/UDF image.')

def is_dlc_url(value):
    try:
        p = https_url(value)
    except (DLCError, ValueError):
        return False
    host = p.hostname.lower()
    name = urllib.parse.unquote(p.path.rsplit('/', 1)[-1])
    m = re.fullmatch('FarmingSimulator(?:20)?25[_-](.+)[.](exe|img)', name, re.I)
    if host != 'giants-software.com' and not host.endswith('.giants-software.com'):
        return False
    if not m:
        return False
    product = re.sub('(?i)(ESD|setup|windows|win64)', '', m.group(1))
    return bool(re.search('[a-z]', product, re.I))

class PortalLinks(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = set()
    def handle_starttag(self, tag, attrs):
        if tag.lower() == 'a':
            for name, value in attrs:
                if name.lower() == 'href' and value:
                    value = urllib.parse.urljoin(PORTAL, value)
                    if is_dlc_url(value):
                        self.links.add(value)

def portal_links(key):
    data = urllib.parse.urlencode({'activationKey': key, 'foobar': 'DOWNLOAD'}).encode()
    req = urllib.request.Request(PORTAL, data=data, headers={'User-Agent': UA})
    with urllib.request.urlopen(req, timeout=45) as response:
        final = https_url(response.url)
        if not final.hostname.lower().endswith('.giants-software.com'):
            raise DLCError('The GIANTS portal redirected to an unexpected host.')
        body = response.read(4194305)
        if len(body) > 4194304:
            raise DLCError('The GIANTS portal returned an unexpectedly large page.')
    parser = PortalLinks()
    parser.feed(body.decode('utf-8', errors='replace'))
    if not parser.links:
        raise DLCError('The portal returned no identifiable FS25 DLC installer; set a direct source override.')
    return sorted(parser.links)

def uploaded_file(inbox, source):
    relative = pathlib.PurePosixPath(source.replace(chr(92), '/'))
    if relative.is_absolute() or '..' in relative.parts or ':' in source:
        raise DLCError('Uploaded sources must be relative to this instance dlc-installers folder.')
    path = (inbox / relative).resolve()
    if inbox.resolve() not in path.parents or not path.is_file():
        raise DLCError('Uploaded DLC installer is missing or outside the upload folder.')
    return path

def fetch(url, target, previous):
    https_url(url)
    headers = {'User-Agent': UA, 'Referer': PORTAL}
    identity = hashlib.sha256(url.encode()).hexdigest()
    reusable = previous.get('source_id') == identity
    if reusable:
        for name, value in (('If-None-Match', previous.get('etag')), ('If-Modified-Since', previous.get('last_modified'))):
            if value:
                headers[name] = value
    req = urllib.request.Request(url, headers=headers)
    try:
        response = urllib.request.urlopen(req, timeout=60)
    except urllib.error.HTTPError as error:
        if error.code == 304 and reusable:
            return None, previous
        raise DLCError('DLC download failed (HTTP ' + str(error.code) + '); refresh or remove its source override.') from None
    with response:
        https_url(response.url)
        length = int(response.headers.get('Content-Length') or 0)
        if length and shutil.disk_usage(target.parent).free < length + 536870912:
            raise DLCError('Not enough free space for the DLC download.')
        downloaded, deadline = 0, time.monotonic() + 7200
        with target.open('wb') as output:
            while True:
                if time.monotonic() > deadline:
                    raise DLCError('DLC download exceeded two hours.')
                block = response.read(1048576)
                if not block:
                    break
                if shutil.disk_usage(target.parent).free < len(block) + 67108864:
                    raise DLCError('Not enough free space to complete the DLC download.')
                output.write(block)
                downloaded += len(block)
        if length and downloaded != length:
            raise DLCError('The DLC download is incomplete.')
        return target, {'source_id': identity, 'etag': response.headers.get('ETag'), 'last_modified': response.headers.get('Last-Modified')}

def prepare(base, keys, sources):
    work, inbox = base / 'work' / 'dlc', base / 'dlc-installers'
    work.mkdir(parents=True, exist_ok=True)
    inbox.mkdir(parents=True, exist_ok=True)
    old = {}
    try:
        old = json.loads((work / 'pending.json').read_text())
    except (OSError, ValueError):
        pass
    jobs, seen, lookups = [], set(), {}
    for alias, key in keys.items():
        print('DLC ' + alias + ': checking installation sources.', flush=True)
        source = sources.get(alias)
        if source:
            urls = [source]
        else:
            if key not in lookups:
                lookups[key] = portal_links(key)
            urls = lookups[key]
        for source in urls:
            remote = source.lower().startswith('https://')
            identity = hashlib.sha256(source.encode()).hexdigest()
            previous = next((j for j in old.get('jobs', []) if j.get('alias') == alias and j.get('source_id') == identity), {})
            cached_name, cached_hash = previous.get('installer', ''), previous.get('sha256', '')
            if not re.fullmatch('[a-f0-9]{64}[.](exe|img)', cached_name) or not cached_name.startswith(cached_hash + '.'):
                previous = {}
            cached = work / previous.get('installer', '.missing')
            if cached.is_symlink() or not cached.is_file() or digest(cached) != previous.get('sha256'):
                previous = {}
            fd, name = tempfile.mkstemp(prefix=alias + '-', suffix='.part', dir=work)
            os.close(fd)
            temporary = pathlib.Path(name)
            try:
                if remote:
                    path, metadata = fetch(source, temporary, previous)
                    if path is None:
                        path = cached
                else:
                    path, metadata = uploaded_file(inbox, source), {'source_id': identity}
                suffix, checksum = kind(path), digest(path)
                if checksum in seen:
                    print('DLC ' + alias + ': identical installer already queued; skipping duplicate.', flush=True)
                    continue
                destination = work / (checksum + suffix)
                if destination.is_symlink():
                    raise DLCError('The DLC installer cache contains an unexpected link.')
                if path != destination and (not destination.exists() or digest(destination) != checksum):
                    if remote and path == temporary:
                        os.replace(path, destination)
                    else:
                        shutil.copyfile(path, temporary)
                        os.replace(temporary, destination)
                if digest(destination) != checksum:
                    raise DLCError('Cached DLC installer failed its checksum check.')
                seen.add(checksum)
                jobs.append(dict(metadata, alias=alias, installer=destination.name, sha256=checksum))
            finally:
                temporary.unlink(missing_ok=True)
    result = {'schema': 1, 'configuration': fingerprint(keys, sources), 'aliases': sorted(keys), 'jobs': jobs}
    temporary = work / 'pending.json.part'
    temporary.write_text(json.dumps(result, indent=2), encoding='utf-8')
    os.replace(temporary, work / 'pending.json')
    print('DLC download preparation complete: ' + str(len(jobs)) + ' installer(s).', flush=True)

def load_amp_entries(base):
    config = base.parent / 'GenericModule.kvp'
    try:
        text = config.read_text(encoding='utf-8-sig')
        settings_lines = [line.partition('=')[2] for line in text.splitlines() if line.startswith('App.AppSettings=')]
        if len(settings_lines) != 1:
            raise ValueError
        settings = json.loads(settings_lines[0])
        if not isinstance(settings, dict):
            raise ValueError
        keys_text = settings.get('DLCProductKeysList', '')
        legacy_text = settings.get('DLCProductKeys', '')
        sources_text = settings.get('DLCInstallSources', '')
        if not isinstance(keys_text, str) or not isinstance(legacy_text, str) or not isinstance(sources_text, str):
            raise ValueError
        if not keys_text.strip():
            if '*' in legacy_text:
                raise DLCError('The legacy DLC password list contains mask characters. Enter the complete NAME=KEY entries in DLC Product Keys (List). No keys were inferred or logged.')
            keys_text = legacy_text
    except (OSError, UnicodeError, ValueError, TypeError):
        raise DLCError('DLC settings could not be read from the AMP instance configuration; no product keys were logged.') from None
    return parse_entries(keys_text, sources_text)

def main():
    if len(sys.argv) == 3 and sys.argv[1] == '--amp-settings':
        base = pathlib.Path(sys.argv[2]).resolve()
        keys, sources = load_amp_entries(base)
    elif len(sys.argv) == 4:
        base = pathlib.Path(sys.argv[3]).resolve()
        keys, sources = parse_entries(sys.argv[1], sys.argv[2])
    else:
        raise DLCError('Invalid DLC preparation arguments.')
    if not keys:
        print('DLCs: disabled (no product keys configured).')
        return
    work = base / 'work' / 'dlc'
    work.mkdir(parents=True, exist_ok=True)
    import fcntl
    with (work / 'operation.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        prepare(base, keys, sources)

if __name__ == '__main__':
    def interrupted(signum, frame):
        raise KeyboardInterrupt
    signal.signal(signal.SIGTERM, interrupted)
    try:
        main()
    except KeyboardInterrupt:
        print('ERROR: DLC preparation interrupted; the previous pending manifest was retained.', file=sys.stderr)
        sys.exit(130)
    except DLCError as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        sys.exit(1)
    except Exception:
        print('ERROR: DLC preparation failed; check connectivity, disk space, permissions and exclusive instance access. Existing pending data was retained.', file=sys.stderr)
        sys.exit(1)
